add(aux3, aux2.fit(), (0,0), W);
label(aux3, " $\textbf{(D)}$ ", (0,0), 3E);
add(aux3, pic4.fit(), (0,0), 35E);

add(mainframe, aux3.fit(), (0,0), W);
label(mainframe, " $\textbf{(E)}$ ", (0,0), 3E);
