picture mainframe;
defaultpen(fontsize(11pt));
picture conePic(picture pic, real r, real h, real sh)
{
	size(pic, 3cm);
    triple eye = (11, 0, 5);
	currentprojection = perspective(eye);
    real R = 1, y = 2;

	triple center = (0, 0, 0);
    triple radPt = (0, R, 0);
