	draw(pic, center--heightPt, linetype("8 8"));
	draw(pic, negRadPt--heightPt--radPt);

	label(pic, (string) r, center--radPt, dir(270));
    if (h != 0)
    {
		label(pic, (string) h, heightPt--center, dir(0));
    }
    if (sh != 0)
    {
		label(pic, (string) sh, heightPt--radPt, dir(0));
    }
    return pic;
}
