import sys

def main():
    data = sys.stdin.read().split()
    idx = 0
    T = int(data[idx]); idx += 1
    for _ in range(T):
        N = int(data[idx]); X = int(data[idx + 1]); Y = int(data[idx + 2]); idx += 3
        A = list(map(int, data[idx:idx + N])); idx += N

        # Case 1: X <= Y  →  never worth using confetti, only full-flight blimps
        if X <= Y:
            max_needed = 0
            for a in A:
                if a > 0:
                    max_needed = max(max_needed, (a + Y - 1) // Y)
            print(max_needed)
            continue

        # Case 2: X > Y  →  greedy from right to left using only confetti blimps
        confetti_used = 0  # number of confetti blimps already launched to the right
        for a in reversed(A):
            remaining = a - confetti_used * Y  # sadness still left for this city
            if remaining > 0:
                need = (remaining + X - 1) // X
                confetti_used += need
        print(confetti_used)

if __name__ == "__main__":
    main()

def deep_copy(obj):
    if isinstance(obj, list):
        return [deep_copy(item) for item in obj]
    elif isinstance(obj, dict):
        return {key: deep_copy(value) for key, value in obj.items()}
    else:
        if isinstance(obj, (int, float, str, bool, type(None))):
            return obj
        raise ValueError("The object must be a list or a dictionary")

if __name__ == "__main__":
    import sys
    import ast
    try:
        inp = sys.stdin.read()
        data = ast.literal_eval(inp)
        if not isinstance(data, (list, dict)):
            raise ValueError
        result = deep_copy(data)
        print(result)
    except Exception:
        print("The object must be a list or a dictionary")

